    const float _coverage_penalty;
    const std::function<bool(DecodingStepResult)> _callback;
  };

struct DecodingOptions {
    size_t beam_size = 1;
    float patience = 1;
    float length_penalty = 0;
    float coverage_penalty = 0;
    float repetition_penalty = 1;
